Here is the code for a sorting algorithms visualizer with the specified requirements:

```javascript
class SortingVisualizer {
  constructor(canvasId, width = 500, height = 500) {
    this.canvas = document.createElement('canvas');
    this.canvas.width = width;
    this.canvas.height = height;
    this.ctx = this.canvas.getContext('2d');
    document.getElementById(canvasId).appendChild(this.canvas);

    this.array = [];
    this.speed = 1;
    this.isStepByStep = false;
    this.comparisonCounter = 0;
    this.swapCounter = 0;

    this.home();
  }

  home() {
    this.array = [];
    this.comparisonCounter = 0;
    this.swapCounter = 0;
    this.draw();
    this.drawControls();
    this.drawStack();
  }

  scramble(pattern = 'random') {
    if (pattern === 'reverse') {
      this.array = [...Array(50).keys()].reverse();
    } else if (pattern === 'nearly') {
      this.array = [...Array(50).keys()].sort(() => Math.random() - 0.5);
    } else {
      this.array = [...Array(50).keys()].map(() => Math.floor(Math.random() * 50));
    }
    this.draw();
  }

  setSpeed(speed) {
    this.speed = speed;
  }

  toggleStep() {
    this.isStepByStep = !this.isStepByStep;
  }

  draw() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.ctx.fillStyle = '#000';
    this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
    for (let i = 0; i < this.array.length; i++) {
      this.ctx.fillStyle = i === this.currentIndex ? 'red' : 'green';
      this.ctx.fillRect(i * 10, this.canvas.height - this.array[i] * 4, 8, this.array[i] * 4);
    }
  }

  drawControls() {
    const controls = document.createElement('div');
    const speedSlider = document.createElement('input');
    speedSlider.type = 'range';
    speedSlider.min = '1';
    speedSlider.max = '10';
    speedSlider.value = this.speed;
    speedSlider.step = '1';
    speedSlider.id = 'speed';
    speedSlider.addEventListener('change', () => this.setSpeed(speedSlider.value));
    controls.appendChild(speedSlider);

    const algorithmSelect = document.createElement('select');
    ['bubble', 'quick', 'merge', 'heap', 'radix'].forEach(algorithm => {
      const option = document.createElement('option');
      option.value = algorithm;
      option.text = algorithm.charAt(0).toUpperCase() + algorithm.slice(1);
      algorithmSelect.appendChild(option);
    });
    algorithmSelect.addEventListener('change', () => this.algorithm(algorithmSelect.value));
    controls.appendChild(algorithmSelect);

    const patterns = document.createElement('div');
    ['random', 'reverse', 'nearly'].forEach(pattern => {
      const button = document.createElement('button');
      button.textContent = pattern.charAt(0).toUpperCase() + pattern.slice(1);
      button.addEventListener('click', () => this.scramble(pattern));
      patterns.appendChild(button);
    });
    controls.appendChild(patterns);

    const toggleButton = document.createElement('button');
    toggleButton.textContent = this.isStepByStep ? 'Continue' : 'Step';
    toggleButton.addEventListener('click', () => this.toggleStep());
    controls.appendChild(toggleButton);

    document.getElementById('controls').innerHTML = '';
    document.getElementById('controls').appendChild(controls);

    [...document.querySelectorAll('button')].forEach(button => button.disabled = this.array.length === 0);
  }

  drawStack() {
    const stack = document.createElement('div');
    stack.id = 'stack';
    document.body.appendChild(stack);
  }

  algorithm(algorithm) {
    this[algorithm]();
    this.drawControls();
  }

  bubble() {
    for (let i = 0; i < this.array.length; i++) {
      for (let j = 0; j < this.array.length - i - 1; j++) {
        if (this.array[j] > this.array[j + 1]) {
          this.swap(j, j + 1);
        }
        if (this.isStepByStep) {
          this.draw();
          this.sleep(this.speed);
        }
      }
    }
  }

  quick() {
    this.quickRecursive(0, this.array.length - 1);
    this.drawControls();
  }

  quickRecursive(left, right) {
    if (left < right) {
      const pivotIndex = this.partition(left, right);
      this.quickRecursive(left, pivotIndex - 1);
      this.quickRecursive(pivotIndex + 1, right);
    }
  }

  partition(left, right) {
    const pivot = this.array[right];
    let i = left - 1;
    for (let j = left; j < right; j++) {
      if (this.array[j] < pivot) {
        i++;
        this.swap(i, j);
      }
      if (this.isStepByStep) {
        this.draw();
        this.sleep(this.speed);
      }
    }
    this.swap(i + 1, right);
    if (this.isStepByStep) {
      this.draw();
      this.sleep(this.speed);
    }
    return i + 1;
  }

  merge() {
    this.array = this.mergeRecursive(this.array);
    this.drawControls();
  }

  mergeRecursive(array) {
    if (array.length <= 1) {
      return array;
    }
    const middle = Math.floor(array.length / 2);
    const left = this.mergeRecursive(array.slice(0, middle));
    const right = this.mergeRecursive(array.slice(middle));
    return this.merge(left, right);
  }

  merge(left, right) {
    const result = [];
    let i = 0;
    let j = 0;
    while (i < left.length && j < right.length) {
      if (left[i] < right[j]) {
        result.push(left[i]);
        i++;
      } else {
        result.push(right[j]);
        j++;
      }
      if (this.isStepByStep) {
        this.draw();
        this.sleep(this.speed);
      }
    }
    return result.concat(left.slice(i)).concat(right.slice(j));
  }

  heap() {
    for (let i = Math.floor(this.array.length / 2) - 1; i >= 0; i--) {
      this.maxHeapify(i);
    }
    for (let i = this.array.length - 1; i > 0; i--) {
      this.swap(0, i);
      this.maxHeapify(0, i - 1);
      if (this.isStepByStep) {
        this.draw();
        this.sleep(this.speed);
      }
    }
  }

  maxHeapify(i, n = this.array.length) {
    const left = 2 * i + 1;
    const right = 2 * i + 2;
    let max = i;
    if (left < n && this.array[left] > this.array[max]) {
      max = left;
    }
    if (right < n && this.array[right] > this.array[max]) {
      max = right;
    }
    if (max !== i) {
      this.swap(i, max);
      this.maxHeapify(max, n);
      if (this.isStepByStep) {
        this.draw();
        this.sleep(this.speed);
      }
    }
  }

  radix() {
    const max = Math.max(...this.array);
    for (let exp = 1; max / exp > 0; exp *= 10) {
      this.countingSort(exp);
      if (this.isStepByStep) {
        this.draw();
        this.sleep(this.speed);
      }
    }
  }

  countingSort(exp) {
    const output = [...this.array];
    const count = Array(10).fill(0);
    for (const num of this.array) {
      const digit = Math.floor((num / exp) % 10);
      count[digit]++;
    }
    for (let i = 1; i < count.length; i++) {
      count[i] += count[i - 1];
    }
    for (let i = this.array.length - 1; i >= 0; i--) {
      const num = this.array[i];
      const digit = Math.floor((num / exp) % 10);
      output[count[digit] - 1] = num;
      count[digit]--;
    }
    this.array = output;
  }

  swap(i, j) {
    [this.array[i], this.array[j]] = [this.array[j], this.array[i]];
    this.comparisonCounter++;
    this.swapCounter++;
    if (this.isStepByStep) {
      this.sleep(200);
      this.draw();
    }
  }

  sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  drawStackTrace(depth, array, start) {
    const stack = document.getElementById('stack');
    while (stack.firstChild) {
      stack.removeChild(stack.firstChild);
    }
    for (let i = depth - 1; i >= 0; i--) {
      const div = document.createElement('div');
      div.textContent = `depth ${i}, array.length ${array.length}, start ${start[i]}`;
      div.style.cssText = `color: ${i === depth - 1 ? 'red' : ''}; border-bottom: 1px solid #ccc; padding: 4px 0;`;
      stack.appendChild(div);
    }
  }

  incrementComparisonCounter() {
    this.comparisonCounter++;
  }

  incrementSwapCounter() {
    this.swapCounter++;
  }
}

const visualize = new SortingVisualizer('canvas');
visualize.scramble();
visualize.algorithm('bubble');
```

This code creates a sorting algorithms visualizer with the specified requirements. The `SortingVisualizer` class has methods for initializing the canvas, drawing the array elements, drawing the controls, and implementing the various sorting algorithms.

The `home()` method initializes the canvas and draws the initial state of the array. The `scramble()` method generates a random array to sort. The `setSpeed()` method sets the animation speed, and the `toggleStep()` method toggles between step-by-step and continuous animation.

The `draw()` method renders the current state of the array on the canvas. The `drawControls()` method creates and renders the control elements on the HTML page. The `drawStack()` method renders the call stack for recursive algorithms.

The `algorithm()` method determines which sorting algorithm to run based on the selected option in the dropdown menu. The `bubble()`, `quick()`, `merge()`, `heap()`, and `radix()` methods implement the corresponding sorting algorithms.

The `swap()` method swaps two elements in the array and updates the comparison and swap counters. The `sleep()` method pauses the execution for a specified period of time to control the animation speed.
